<script setup lang="ts">
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { ArrowLeft, Building2, Check, Mail, Phone, UserRound } from 'lucide-vue-next'

type Account={company?:string;fullName?:string;email?:string;phone?:string;password?:string}
const router=useRouter(),saved=ref(false),error=ref('')
const account:Account=JSON.parse(localStorage.getItem('qr-menu-account')||'{}')
const names=(account.fullName||localStorage.getItem('qr-menu-profile-name')||'').trim().split(/\s+/)
const firstName=ref(names[0]||''),lastName=ref(names.slice(1).join(' ')),company=ref(account.company||''),email=ref(account.email||''),phone=ref(account.phone||'')
function save(){if(!firstName.value.trim()||!lastName.value.trim()){error.value='Lütfen ad ve soyadınızı yazın.';return}const fullName=`${firstName.value.trim()} ${lastName.value.trim()}`;localStorage.setItem('qr-menu-account',JSON.stringify({...account,company:company.value.trim(),fullName,email:email.value.trim(),phone:phone.value.trim()}));localStorage.setItem('qr-menu-profile-name',fullName);window.dispatchEvent(new Event('qr-menu-profile-updated'));error.value='';saved.value=true;setTimeout(()=>saved.value=false,1800)}
</script>

<template><div class="account-page"><header><div><span>HESAP AYARLARI</span><h2>Profil bilgileriniz</h2><p>Kayıt sırasında verdiğiniz bilgileri görüntüleyin ve güncelleyin.</p></div><button @click="router.push('/admin')"><ArrowLeft :size="16"/> Panele dön</button></header><section class="account-card"><div class="profile-summary"><div class="profile-avatar">{{firstName.slice(0,1).toUpperCase()}}{{lastName.slice(0,1).toUpperCase()}}</div><div><h3>{{firstName||'Ad'}} {{lastName||'Soyad'}}</h3><p>{{email||'E-posta bilgisi yok'}}</p></div><span>İşletme hesabı</span></div><form @submit.prevent="save"><label class="wide"><span><Building2 :size="15"/>Firma ticari ünvanı</span><input v-model="company" placeholder="Firma veya restoran adı"/></label><div class="form-grid"><label><span><UserRound :size="15"/>Ad</span><input v-model="firstName" placeholder="Adınız" required/></label><label><span><UserRound :size="15"/>Soyad</span><input v-model="lastName" placeholder="Soyadınız" required/></label></div><div class="form-grid"><label><span><Mail :size="15"/>E-posta</span><input v-model="email" type="email" placeholder="ornek@restoran.com"/></label><label><span><Phone :size="15"/>Cep telefonu</span><input v-model="phone" type="tel" placeholder="05XX XXX XX XX"/></label></div><p v-if="error" class="form-error">{{error}}</p><div class="form-actions"><small>Değişiklikler hesabınıza otomatik kaydedilir.</small><button type="submit"><Check :size="17"/>{{saved?'Kaydedildi':'Bilgileri kaydet'}}</button></div></form></section></div></template>

<style scoped>
