;border-top:1px solid var(--line);padding-top:20px;margin-top:7px}.form-actions small{font-size:9px;color:#969e98}.form-actions button{height:43px;border:0;border-radius:10px;background:#202522;color:#fff;padding:0 17px;display:flex;align-items:center;gap:8px;font-size:11px;font-weight:800;cursor:pointer}.form-actions button:hover{background:var(--orange)}@media(max-width:650px){.account-page>header{align-items:stretch;flex-direction:column}.account-page header>button{justify-content:center}.profile-summary>span{display:none}.account-card form{padding:20px}.form-grid{grid-template-columns:1fr}.form-actions{align-items:stretch;flex-direction:column;gap:13px}.form-actions button{justify-content:center}}
</style>
